head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkcombobox > P > renderType]<br/>컴포넌트가 렌더링 되는 방식을 설정합니다.",
    "validation" : [
        "미설정 시 table 태그를 갖는 div 태그로 렌더링됩니다.",        
        "component 설정 시 table 태그를 갖는 div 태그로 렌더링됩니다.",
        "미설정 또는 component 설정 시 table 태그는 두 개의 td 태그로 구성되며 선택된 아이템들의 값을 표시하는 라벨 표시 영역과 드롭다운 버튼이 td 태그에 렌더링됩니다.",
        "native 설정 시 label 과 a 요소를 갖는 중첩 div 태그로 렌더링됩니다.",
        "native 설정 시 label 태그를 갖는 div 태그로 선택된 아이템들의 값을 표시하는 라벨 표시 영역이 렌더링됩니다.",
        "native 설정 시 a 태그로 드롭다운 버튼 영역이 렌더링됩니다.",
        "렌더링 되는 태그에 따라 'w2checkcombobox', 'w2checkcombobox_acc', 'w2checkcombobox_label', 'w2checkcombobox_col_button', 'w2checkcombobox_acc_custom' 등의 클래스가 추가됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        renderType : con_renderType.getText(),        
    }

    let cList = $c.gcm.createCList(properties)

    // comp 생성 함수 호출
    $c.gcm.createBasicCheckComboBox(cList);
}



scwin.btn_getRenderType_onclick = function (e) {
    let rtn = '';

    rtn = target1.render.tagName;        
    wf_body_bottom.getObj("scwin").setReturnValue("Main tagName : " + rtn);

    rtn = target1.render.className;
    wf_body_bottom.getObj("scwin").setReturnValue("Main className : " + rtn);

    // id가 "target1"을 포함하는 모든 요소 찾기
    let matchingElements = document.querySelectorAll('[id*="target1"]');

    matchingElements.forEach(function(element) {
        let childElements = element.querySelectorAll("*"); // 모든 하위 요소 선택

        // 하위 요소들의 태그명 출력
        childElements.forEach(function(child) {
            rtn = child.tagName;
            wf_body_bottom.getObj("scwin").setReturnValue("Child tagName : " + rtn);

            rtn = child.className;
            wf_body_bottom.getObj("scwin").setReturnValue("Child className : " + rtn);
        });
    });
};
